def transform(grid):
    h, w = len(grid), len(grid[0])
    line_keys = [
        (lambda r, c: r),
        (lambda r, c: c),
        (lambda r, c: r + c),
        (lambda r, c: c - r),
    ]
    candidates = []
    for key in line_keys:
        lines = {}
        valid = True
        for r, row in enumerate(grid):
            for c, color in enumerate(row):
                if color:
                    k = key(r, c)
                    if k in lines and lines[k][0] != color:
                        valid = False
                        break
                    if k not in lines:
                        lines[k] = [color, 0]
                    lines[k][1] += 1
            if not valid:
                break
        if valid and lines:
            # The intended stripe direction groups the marks into the fewest,
            # longest monochrome lines. The number of such lines is the cycle.
            n = len(lines)
            phase = {}
            for k, (color, _) in lines.items():
                residue = k % n
                if residue in phase and phase[residue] != color:
                    valid = False
                    break
                phase[residue] = color
            if valid and len(phase) == n:
                strength = (sum(count * count for _, count in lines.values()),
                            max(count for _, count in lines.values()),
                            -n)
                candidates.append((strength, key, n, phase))
    if not candidates:
        raise ValueError("could not infer periodic stripe lines")
    _, key, n, phase = max(candidates, key=lambda item: item[0])
    return [[phase[key(r, c) % n] for c in range(w)] for r in range(h)]
